--
-- DDL replay test schema: one or more instances of every schema level object type that YADAMU replays when copying Postgres to Postgres.
-- The schema is cloned with DDL_AND_DATA and DDL_ONLY operations. The DDL generated from the clone must match the DDL generated from this schema.
--
drop schema if exists t_pgddl cascade;
--
create schema t_pgddl;
--
set search_path to t_pgddl, public;
--
-- Types
--
create type mood as enum ('sad', 'ok', 'happy');
create type "Mixed Case Enum" as enum ('Alpha', 'beta', 'with space');
create domain positive_int as integer not null default 1 constraint positive_int_check check (value > 0);
create domain email_address as text collate "C" constraint email_address_check check (value ~ '@');
create type address as (street text, city varchar(64), zip char(5));
create type float_range as range (subtype = float8, subtype_diff = float8mi);
create collation case_insensitive (provider = icu, locale = 'und-u-ks-level2', deterministic = false);
--
-- Sequences
--
create sequence standalone_seq as bigint increment by 5 minvalue 10 maxvalue 100000 start with 10 cache 1 cycle;
select setval('standalone_seq', 55);
create sequence unused_seq;
--
-- Functions and procedures
--
create function add_one(i integer) returns integer language sql immutable as $$ select i + 1 $$;
create function full_name(first_name text, last_name text) returns text language sql immutable as $$ select first_name || ' ' || last_name $$;
create function overloaded(i integer) returns text language sql immutable as $$ select 'integer' $$;
create function overloaded(t text) returns text language sql immutable as $$ select 'text' $$;
create function sum_all(variadic v integer[]) returns integer language sql immutable as $$ select sum(x)::integer from unnest(v) x $$;
create function "Mixed Case Function"(p_mood mood default 'ok') returns mood language plpgsql stable as $$ begin return p_mood; end $$;
create function set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at := now(); return new; end $$;
create function audit_statement() returns trigger language plpgsql as $$ begin insert into t_pgddl.audit_log(operation, table_name) values (tg_op, tg_table_name); return null; end $$;
create function check_amount() returns trigger language plpgsql as $$ begin if new.amount < 0 then raise exception 'negative amount'; end if; return new; end $$;
create function active_people_insert() returns trigger language plpgsql as $$ begin insert into t_pgddl.people(first_name, last_name, email) values (new.first_name, new.last_name, new.email); return new; end $$;
create aggregate product(numeric) (sfunc = numeric_mul, stype = numeric, initcond = '1');
--
-- Tables
--
create table people (
  id              integer generated always as identity primary key,
  first_name      text not null,
  last_name       text not null,
  full_name       text generated always as (full_name(first_name, last_name)) stored,
  current_mood    mood default 'ok',
  past_moods      mood[],
  home            address,
  age             positive_int,
  email           email_address,
  nickname        text collate case_insensitive,
  "Quoted Column" text collate "C",
  height_cm       numeric(5,1),
  created_at      timestamptz default now(),
  updated_at      timestamptz,
  dropped_column  text,
  search          tsvector,
  constraint people_email_key unique (email) deferrable initially deferred,
  constraint people_height_check check (height_cm > 0)
);
alter table people drop column dropped_column;
alter table people add constraint people_age_check check ((age)::integer < 150) not valid;
--
create table "Mixed Case Table" (
  "Id"            serial primary key,
  "Value"         "Mixed Case Enum",
  "Range"         float_range
);
--
create table "select" (
  "from"          integer primary key,
  "where"         text
);
--
create table orders (
  id              bigserial primary key,
  person_id       integer not null references people(id) on delete cascade,
  parent_order_id bigint references orders(id) deferrable initially immediate,
  amount          numeric(12,2) not null,
  status          mood
);
--
create table products (
  sku             text,
  region          char(2),
  description     text,
  identity_col    bigint generated by default as identity (start with 100 increment by 10),
  primary key (sku, region) include (description)
);
--
create table order_lines (
  order_id        bigint references orders(id),
  line_no         smallint,
  sku             text,
  region          char(2),
  quantity        integer default 1 check (quantity > 0),
  primary key (order_id, line_no),
  foreign key (sku, region) references products(sku, region) match full on update cascade
);
--
create table bookings (
  room            integer,
  during          tsrange,
  constraint bookings_no_overlap exclude using gist (during with &&)
);
--
create unlogged table session_cache (
  key             text primary key,
  value           jsonb
);
--
create table audit_log (
  id              bigint generated by default as identity primary key,
  operation       text,
  table_name      text,
  logged_at       timestamptz default now()
);
--
create table counters (
  name            text primary key,
  value           bigint default nextval('standalone_seq')
);
--
create table measurements (
  id              bigint not null,
  logdate         date not null,
  region          text not null,
  reading         double precision,
  primary key (id, logdate, region)
) partition by range (logdate);
create table measurements_2025 partition of measurements for values from ('2025-01-01') to ('2026-01-01');
create table measurements_2026 partition of measurements for values from ('2026-01-01') to ('2027-01-01') partition by list (region);
create table measurements_2026_east partition of measurements_2026 for values in ('east');
create table measurements_2026_west partition of measurements_2026 for values in ('west');
create table measurements_default partition of measurements default;
--
create table hashed (
  id              integer primary key,
  payload         text
) partition by hash (id);
create table hashed_0 partition of hashed for values with (modulus 2, remainder 0);
create table hashed_1 partition of hashed for values with (modulus 2, remainder 1);
--
create table vehicles (
  id              integer primary key,
  name            text
);
create table cars (
  doors           integer
) inherits (vehicles);
--
create table typed_addresses of address (
  primary key (street)
);
--
-- Indexes
--
create index people_last_name_idx on people (last_name);
create index people_lower_email_idx on people (lower(email));
create index people_happy_idx on people (created_at desc nulls last) where current_mood = 'happy';
create index people_past_moods_idx on people using gin (past_moods);
create index people_search_idx on people using gin (search);
create index people_created_brin_idx on people using brin (created_at) with (pages_per_range = 32);
create index people_first_name_hash_idx on people using hash (first_name);
create index people_name_pattern_idx on people (first_name text_pattern_ops, last_name collate "C");
create unique index people_nickname_idx on people (nickname) with (fillfactor = 70);
create index orders_person_idx on orders (person_id) include (amount);
create index bookings_room_idx on bookings (room);
create index measurements_region_idx on measurements (region);
create index "Mixed Case Index" on "Mixed Case Table" ("Value");
--
create statistics people_name_stats (dependencies, ndistinct) on first_name, last_name from people;
--
-- Views
--
create view active_people as select id, first_name, last_name, email from people where current_mood <> 'sad' with cascaded check option;
create view people_names with (security_barrier = true) as select id, full_name from people;
create view active_people_names as select a.id, n.full_name from active_people a join people_names n using (id);
create view order_totals (person_id, order_count, total) as select person_id, count(*), sum(amount) from orders group by person_id;
create recursive view order_tree (id, parent_order_id, depth) as select id, parent_order_id, 0 from orders where parent_order_id is null union all select o.id, o.parent_order_id, t.depth + 1 from orders o join order_tree t on o.parent_order_id = t.id;
create view mood_names as select overloaded(id) kind, "Mixed Case Function"(current_mood) mood from people;
create materialized view mood_counts as select current_mood, count(*) people from people group by current_mood;
create unique index mood_counts_idx on mood_counts (current_mood);
create materialized view empty_summary as select region, count(*) readings from measurements group by region with no data;
--
-- Functions that depend on table and view row types
--
create function people_by_mood(p_mood mood) returns setof people language sql stable as $$ select * from t_pgddl.people where current_mood = p_mood $$;
create function active_person(p_id integer) returns active_people language sql stable as $$ select * from t_pgddl.active_people where id = p_id $$;
create procedure reset_counter(p_name text, p_value bigint default 0) language plpgsql as $$ begin update t_pgddl.counters set value = p_value where name = p_name; end $$;
--
-- Triggers
--
create trigger people_updated_at before update on people for each row execute function set_updated_at();
create trigger people_audit after insert or update or delete on people for each statement execute function audit_statement();
create trigger orders_amount_check before insert or update of amount on orders for each row when (new.amount is not null) execute function check_amount();
create trigger orders_audit after delete on orders for each statement execute function audit_statement();
alter table orders disable trigger orders_audit;
create constraint trigger order_lines_check after insert on order_lines deferrable initially deferred for each row execute function audit_statement();
create trigger active_people_insert instead of insert on active_people for each row execute function active_people_insert();
--
-- Rules, row level security and comments
--
create rule counters_no_delete as on delete to counters do instead nothing;
alter table session_cache enable row level security;
create policy session_cache_read on session_cache for select using (true);
create policy session_cache_write on session_cache for insert with check (key <> '');
comment on table people is 'People, with every kind of column';
comment on column people.full_name is 'Generated from first_name and last_name';
comment on type mood is 'How someone feels';
comment on function add_one(integer) is 'Adds one';
comment on view active_people is 'People who are not sad';
comment on index people_last_name_idx is 'Lookup by last name';
--
-- Data
--
